mapper.select:
        SELECT m.*,n.CHARGE_VALUE,n.CHARGE_RATE,n.FEE_MAXI,n.FEE_MINI,n.GRADE_AMOUNT,n.IS_CLUDE_STARTAMT
        FROM TRD_FEE_CONFIG m
        inner join TRD_FEE_CONFIG_DETAIL n on m.SEQ_NO=n.CONFIG_SEQ_NO


			 m.EFF_DATE <= #{tradeDate,jdbcType=DATE} 


			 and m.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}


			 and m.TRADE_MARKET_MODE = #{tradeMarketMode,jdbcType=VARCHAR}


			   and m.WINDTYPEONE = #{type6,jdbcType=VARCHAR}


			   and m.WINDTYPETWO = #{type7,jdbcType=VARCHAR}


	         and m.FEE_TYPE = #{feeType,jdbcType=VARCHAR}


			 and m.TRADE_TYPE = #{finprodType2,jdbcType=VARCHAR}


			 and m.PS = #{ps,jdbcType=VARCHAR}


			 and m.REGIST_ORG = #{registOrg,jdbcType=VARCHAR}


			 and m.TERM_TYPE = #{termType,jdbcType=VARCHAR}


			 and m.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}


			 and (n.IS_MLTI is null OR n.IS_MLTI = 'N')



			 and (n.IS_MLTI = 'Y'  OR (m.CHARGE_TYPE ='01' and ((n.IS_MLTI is null OR n.IS_MLTI = 'N') and not EXISTS (
			 		select 1 FROM TRD_FEE_CONFIG m
						INNER JOIN TRD_FEE_CONFIG_DETAIL n
						ON m.SEQ_NO        =n.CONFIG_SEQ_NO
					where n.IS_MLTI = 'Y' 

					and  m.EFF_DATE <= #{tradeDate,jdbcType=DATE} 


					 and m.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}


			         and m.FEE_TYPE = #{feeType,jdbcType=VARCHAR}


					 and m.TRADE_TYPE = #{finprodType2,jdbcType=VARCHAR}


					 and m.PS = #{ps,jdbcType=VARCHAR}


					 and m.REGIST_ORG = #{registOrg,jdbcType=VARCHAR}


					 and m.TERM_TYPE = #{termType,jdbcType=VARCHAR}


					 and m.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}

			 ))))


       order by m.EFF_DATE desc,n.GRADE_AMOUNT asc
